#pragma once
#include "rinkfit/joint_al.hpp"
namespace rinkfit {
// Optional exact contract for a configured stage. Inspect the constructed Ceres
// graph, including a manifold's real PlusJacobian; a config name is not evidence.
inline eventio::Json assert_joint_capture_stage_v1(const JointALBuilder&b,ceres::Problem&problem,const eventio::Json&cfg){
 eventio::Json report={{"schema","rinkfit.actual_capture_Ceres_scalar_stage_guard.v1"},{"enabled",cfg.contains("audit_expected_free_physical_blocks")},{"passed",false}};
 if(cfg.contains("audit_expected_free_physical_blocks")){
  std::map<std::string,eventio::Json>expected;std::set<int>expected_indices;for(const auto&v:cfg.at("audit_expected_free_physical_blocks")){const auto name=v.at("block_name").get<std::string>();const int index=v.at("block_index");if(!expected.emplace(name,v).second||!expected_indices.insert(index).second)throw std::runtime_error("duplicate capture physical stage allowlist entry");}
  eventio::Json actual=eventio::Json::array();std::size_t dimensions=0;for(std::size_t index=0;index<b.core.model.blocks.size();++index){const auto&block=b.core.model.blocks[index];const auto*x=block.values.data();if(!problem.HasParameterBlock(x)||problem.IsParameterBlockConstant(x))continue;const int n=problem.ParameterBlockSize(x),t=problem.ParameterBlockTangentSize(x);if(t<=0)continue;auto it=expected.find(block.name);if(it==expected.end())throw std::runtime_error("capture has unapproved free physical block: "+block.name);const auto&e=it->second;if(e.at("block_index").get<std::size_t>()!=index||e.at("ambient_size").get<int>()!=n||e.at("expected_tangent_size").get<int>()!=t)throw std::runtime_error("capture physical stage size/index changed: "+block.name);std::vector<double>J(n*t,0.);if(const auto*m=problem.GetManifold(x)){if(!m->PlusJacobian(x,J.data()))throw std::runtime_error("capture stage PlusJacobian unavailable: "+block.name);}else for(int k=0;k<n;++k)J[k*t+k]=1.;std::vector<int>free_rows;for(int k=0;k<n;++k){bool nonzero=false;for(int j=0;j<t;++j){const double a=J[k*t+j];if(!std::isfinite(a))throw std::runtime_error("nonfinite capture PlusJacobian: "+block.name);nonzero|=a!=0.;}if(nonzero)free_rows.push_back(k);}auto allowed=e.at("free_ambient_indices").get<std::vector<int>>();std::sort(allowed.begin(),allowed.end());if(std::adjacent_find(allowed.begin(),allowed.end())!=allowed.end()||allowed!=free_rows)throw std::runtime_error("capture free ambient scalar rows changed: "+block.name);actual.push_back({{"block_index",index},{"block_name",block.name},{"ambient",n},{"tangent",t},{"actual_free_ambient_rows",free_rows}});dimensions+=t;expected.erase(it);}
  if(!expected.empty())throw std::runtime_error("capture configured physical freedom was not registered: "+expected.begin()->first);report["free_physical_blocks"]=actual.size();report["physical_tangent_dimensions"]=dimensions;report["actual"]=std::move(actual);
 }
 eventio::Json counts=eventio::Json::object();for(const auto&r:b.core.packet.rows)if(r.active)counts[r.shot_id]=counts.value(r.shot_id,std::size_t(0))+1;if(cfg.contains("audit_expected_source_counts")&&counts!=cfg.at("audit_expected_source_counts"))throw std::runtime_error("capture actual per-shot active source counts differ from configured immutable stage");report["actual_active_source_counts"]=counts;report["source_counts_guard_enabled"]=cfg.contains("audit_expected_source_counts");report["manifold_rows_checked_with_exact_nonzero_PlusJacobian"]=true;report["parameters_or_stage_modified"]=false;report["passed"]=true;return report;
}
}
